wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{kb_read, tool_llm};

/// Precondition from the node contract: `requires len(question) <= 512`.
const MAX_QUESTION_CHARS: usize = 512;

/// Bounds the tool-orchestration loop so a model that keeps asking for tools
/// cannot spin forever.
const MAX_TOOL_ROUNDS: usize = 4;

/// Bounds how many knowledge-base hits are fed back to the model per lookup.
const MAX_LOOKUP_HITS: usize = 10;

const SYSTEM: &str = "You are a customer-support assistant. Answer the customer's \
question using only the knowledge provided. If the knowledge does not cover the \
question, say so plainly. You may call the `lookup` tool to search the knowledge \
base for more material.";

struct Node;

fn intent_label(intent: crate::aap::caps::types::Intent) -> &'static str {
    use crate::aap::caps::types::Intent;
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn render_knowledge(knowledge: &[String]) -> String {
    if knowledge.is_empty() {
        return "(none)".to_string();
    }
    knowledge
        .iter()
        .map(|entry| format!("- {entry}"))
        .collect::<Vec<_>>()
        .join("\n")
}

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return fail("question exceeds the 512-character limit");
        }

        let mut transcript = format!(
            "Intent: {}\nQuestion: {}\n\nKnowledge:\n{}\n",
            intent_label(ctx.intent),
            ctx.question,
            render_knowledge(&ctx.knowledge),
        );

        for _ in 0..MAX_TOOL_ROUNDS {
            match tool_llm::generate(SYSTEM, &transcript) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(request) => {
                    if request.tool != "lookup" {
                        return fail("model requested a tool outside its scope");
                    }

                    let hits = kb_read::lookup(&request.query);

                    transcript.push_str("\nTool call: lookup(");
                    transcript.push_str(&request.query);
                    transcript.push_str(")\nTool result:\n");
                    if hits.is_empty() {
                        transcript.push_str("(no matches)\n");
                    } else {
                        for hit in hits.iter().take(MAX_LOOKUP_HITS) {
                            transcript.push_str("- ");
                            transcript.push_str(hit);
                            transcript.push('\n');
                        }
                    }
                }
            }
        }

        fail("tool-call limit reached without a final answer")
    }
}

export!(Node);
```

